style.css:
@-moz-document domain("youtube.com") {
/* --- CORE LAYOUT & CLIPPING --- */
  [style*="position: absolute; width: 100%; height: 100%;"] {
    display: none;
  }
  html {
    scrollbar-color: var(--acc) var(--bg2) !important;
  }
  body {
    overflow-x: hidden !important;
  }
  
  /* 1. MAKE MAIN APP TRANSPARENT SO IMAGE SHOWS */
  ytd-app {
    z-index: -11;
    background: transparent !important; /* CHANGED FROM var(--bg2) */
  }

  /* 2. INSERT YOUR IMAGE HERE */
  ytd-app::before {
    content: '';
    position: fixed;
    width: 100%;
    height: 100%;
    z-index: -10;
    /* YOUR IMAGE URL IS HERE */
    background: url("https://i.pinimg.com/1200x/5d/a0/eb/5da0eb88be43347ab8735b0507f6db1a.jpg") no-repeat center center fixed !important;
    background-size: cover !important;
  }

  /* 3. THE OVERLAY (Shadow) */
  ytd-app::after {
    content: "";
    width: 100%;
    height: 100%;
    opacity: var(--bgoppa); /* Controlled by variable at bottom */
    background: var(--bg2); 
    position: fixed;
    display: block;
    z-index: -3;
    top: 0;
    bottom: 0;
  }

  #guide-content.ytd-app {
    background: transparent;
  }
  #guide-content.ytd-app::after {
    content: "";
    width: 100%;
    height: 100%;
    opacity: var(--bgoppa);
    background: var(--bg2);
    position: fixed;
    display: block;
    z-index: -2;
    top: 0;
    left: 0;
    bottom: 0;
  }
  #scrim.tp-yt-app-drawer {
    background: var(--bg2);
    background-blend-mode: normal;
  }

  /* --- HEADER & MASTHEAD --- */
  #container.ytd-masthead {
    height: 40px;
    padding: 0 16px 15px 16px;
    background: rgba(0,0,0,0.8) !important; /* Semi-transparent header */
    border-bottom: 1px solid var(--acc);
    clip-path: polygon(100% 0, 100% 90%, 85% 90%, 75% 175%, 75% 5000%, 25% 5000%, 20% 100%, 19% 90%, 0 90%, 0 0);
  }
  #background.ytd-masthead {
    background: transparent !important;
    box-shadow: 0 0 20px var(--acc4);
  }
  ytd-searchbox.ytd-masthead {
    margin: 10px 0px 0px 95px;
  }
  #voice-search-button.ytd-masthead {
    margin-left: 2em;
  }
  #center.ytd-masthead {
    margin-top: 12px;
  }
  ytd-searchbox[has-focus] #container.ytd-searchbox {
    border: 1px solid var(--acc);
    box-shadow: inset 0 1px 2px rgba(0,0,0,0.3);
    margin-left: 0;
    transition: 0.2s;
    padding: 2px 4px 2px 48px;
  }

  /* --- LOGO ANIMATIONS --- */
  .ytd-topbar-logo-renderer:hover {
    animation-name: rubberBand;
    animation-duration: 1s;
    animation-delay: 10s;
    animation-fill-mode: both;
    animation-iteration-count: 5;
  }
  ytd-topbar-logo-renderer:not(:active) {
    animation: yadlogo2;
    animation-duration: 1s;
    animation-timing-function: ease;
    animation-iteration-count: 1;
    animation-direction: normal;
    animation-fill-mode: none;
  }

  /* --- ANIMATION KEYFRAMES --- */
  @keyframes yadlogo2 {
    0% { transform: scaleY(2); filter: blur(4px); opacity: 0; }
    100% { transform: scaleY(1); filter: blur(0); opacity: 1; }
  }
  @keyframes rubberBand {
    0% { transform: scale3d(1, 1, 1); }
    30% { transform: scale3d(1.25, 0.75, 1); }
    40% { transform: scale3d(0.75, 1.25, 1); }
    50% { transform: scale3d(1.15, 0.85, 1); }
    65% { transform: scale3d(0.95, 1.05, 1); }
    75% { transform: scale3d(1.05, 0.95, 1); }
    100% { transform: scale3d(1, 1, 1); }
  }

  /* --- SEARCH & MENUS --- */
  .gsfs { color: var(--tx1) !important; }
  .sbsb_d { background: var(--bg0); }
  html[darker-dark-theme] .sbqs_c:before { filter: invert(1); }
  html[dark] .sbqs_c:before { filter: invert(0) !important; }

  /* Popups / Dialogs Geometry */
  yt-report-form-modal-renderer[dialog][dialog][dialog],
  tp-yt-paper-dialog,
  tp-yt-paper-menu-button[vertical-align=top] .dropdown-content.tp-yt-paper-menu-button,
  ytd-multi-page-menu-renderer,
  ytd-menu-popup-renderer,
  .yt-contextual-sheet-layout-wiz,
  .ytp-popup {
    opacity: var(--oppa);
    border-radius: 0;
    backdrop-filter: none;
    --background-color: var(--bg2);
    clip-path: var(--poly1);
  }

  /* Popup Borders & Backgrounds */
  yt-report-form-modal-renderer[dialog][dialog][dialog]::before,
  tp-yt-paper-dialog::before,
  tp-yt-paper-menu-button[vertical-align=top] .dropdown-content.tp-yt-paper-menu-button::before,
  ytd-multi-page-menu-renderer::before,
  ytd-menu-popup-renderer::before,
  .yt-contextual-sheet-layout-wiz::before,
  .ytp-popup::before {
    content: ""; position: absolute; inset: 0; background: var(--acc); z-index: -2;
  }

  yt-report-form-modal-renderer[dialog][dialog][dialog]::after,
  tp-yt-paper-dialog::after,
  tp-yt-paper-menu-button[vertical-align=top] .dropdown-content.tp-yt-paper-menu-button::after,
  ytd-multi-page-menu-renderer::after,
  ytd-menu-popup-renderer::after,
  .yt-contextual-sheet-layout-wiz::after,
  .ytp-popup::after {
    content: ""; position: absolute; inset: 0; background: var(--bg2); z-index: -1; clip-path: var(--poly2);
    animation: galaw2 0.2s 1 linear;
  }

  .ytd-menu-title-renderer { color: var(--tx1); }
  #offRadio.tp-yt-paper-radio-button,
  #checkbox.tp-yt-paper-checkbox { border-color: var(--acc); }

  /* --- BUTTONS & INTERACTION --- */
  .yt-spec-button-shape-next--mono.yt-spec-button-shape-next--tonal {
    color: #000;
    background: var(--acc);
    padding: 16px 32px;
    position: relative;
    cursor: pointer;
    border-radius: 0px;
    transition: box-shadow 0.1s ease, background 0.3s ease;
    clip-path: polygon(0 0, calc(100% - var(--es)) 0, 100% var(--es), 100% calc(100% - 0%), calc(100% - var(--es)) 100%, var(--es) 100%, 0 calc(100% - var(--es)), 0 var(--es));
    overflow: hidden;
    border: none;
  }
  .yt-spec-button-shape-next--mono.yt-spec-button-shape-next--tonal:hover {
    background: #fff;
    box-shadow: inset -4px -4px 12px var(--acc), inset 4px 4px 12px var(--acc2), 5px 5px 18px rgba(0,0,0,0.9);
    color: #000;
  }
  
  /* Search Button */
  .ytSearchboxComponentSearchButton,
  .ytSearchboxComponentSearchButtonDark,
  #search-icon-legacy.ytd-searchbox {
    background: linear-gradient(135deg, var(--acc) calc(115% - var(--es)), transparent 0%);
    border-radius: 0px; border: 0; margin-left: 4px;
  }
  .ytSearchboxComponentSearchButton:hover,
  #search-icon-legacy.ytd-searchbox:hover {
    background: linear-gradient(135deg, var(--acc) calc(115% - var(--es)), transparent 0%);
    opacity: 0.9;
  }

  ytd-searchbox[system-icons] #search-icon-legacy.ytd-searchbox yt-icon.ytd-searchbox {
    color: #000; stroke: #000; /* Icon inside button is black */
  }

  /* Input Boxes */
  .ytSearchboxComponentInputBox,
  .ytSearchboxComponentInputBoxDark,
  #container.ytd-searchbox {
    border: 0px solid transparent; opacity: var(--oppa); border-radius: 0; clip-path: var(--poly-search);
    --background-color: var(--bg2); --ses1: var(--es); --sbw1: var(--bw);
  }
  .ytSearchboxComponentInputBox::before,
  #container.ytd-searchbox::before {
    content: ""; position: absolute; inset: 0; background: var(--acc); z-index: -2;
  }
  .ytSearchboxComponentInputBox::after,
  #container.ytd-searchbox::after {
    content: ""; position: absolute; inset: 0; background: var(--bg2); z-index: -1; clip-path: var(--poly-search2);
  }

  /* Search Suggestions */
  .ytSearchboxComponentSuggestionsContainer, .sbsb_a, .sbdd_b, .gstl_50.sbdd_a {
    border-radius: 0; --background-color: var(--bg2); opacity: var(--oppa);
    clip-path: var(--poly-search-down); border: 0px solid transparent;
  }
  .ytSearchboxComponentSuggestionsContainer::before, .sbsb_a::before {
    content: ""; position: absolute; inset: 0; background: var(--acc); z-index: -5;
  }
  .ytSearchboxComponentSuggestionsContainer::after, .sbsb_a::after {
    content: ""; position: absolute; inset: 0; background: var(--bg2); z-index: -1; clip-path: var(--poly-search-down2);
  }

  /* --- ICONS & SVGS --- */
  .guide-icon.ytd-mini-guide-entry-renderer,
  .guide-icon.ytd-guide-entry-renderer {
    background: var(--acc3); box-shadow: 0 0 0 1px var(--acc); border-radius: 0px; padding: 3px;
  }
  .guide-icon.ytd-mini-guide-entry-renderer::before,
  .guide-icon.ytd-guide-entry-renderer::before {
    content: ""; width: 12px; height: 3px; position: absolute; background: var(--acc); top: -3px; right: -2px;
  }
  
  /* Force all SVG Icons to Gold */
  g#youtube-red-paths_yt2079, [id^="yt-logo-updated_yt"], 
  [d^="M14.4848 20C14.4848 20"], [d^="m13.497 4.898"], 
  [d^="M21 6H3V5h18v1zm0 5H3v1h18v-1zm0 6H3v1h18v-1z"] {
    fill: var(--acc) !important;
  }
  
  /* Skeleton Loading */
  .masthead-skeleton-icon, html .watch-skeleton .skeleton-bg-color {
    background: var(--bg0);
  }

  /* Player Settings Badges (HD, 4K) */
  .ytp-settings-button.ytp-hd-quality-badge:after,
  .ytp-settings-button.ytp-4k-quality-badge:after,
  .ytp-chrome-controls .ytp-button[aria-pressed]:after {
    background-color: var(--acc);
  }
  .ytp-swatch-color-white { color: var(--acc); }

  /* Grid & Chips */
  #text.ytd-channel-name, #video-title.ytd-rich-grid-media { font-size: var(--vprc); color: var(--tx1); }
  
  yt-chip-cloud-chip-renderer[chip-style=STYLE_HOME_FILTER][selected],
  #text.yt-chip-cloud-chip-renderer:hover { color: #000; } /* Text on selected chip */

  yt-chip-cloud-chip-renderer[chip-style=STYLE_HOME_FILTER] {
    background-color: var(--bg0);
    backdrop-filter: blur(2px);
  }
  yt-chip-cloud-chip-renderer[chip-style^=STYLE]::before {
    content: ""; position: absolute; inset: 0; background: var(--acc); z-index: -5;
  }
  yt-chip-cloud-chip-renderer[chip-style^=STYLE]::after {
    content: ""; position: absolute; inset: 0; color: var(--tx1); background: var(--bg2); z-index: -1; clip-path: var(--poly-filter-down2);
  }

  /* Hover Effects */
  .title.ytd-guide-entry-renderer:hover,
  tp-yt-paper-item.ytd-compact-link-renderer:hover {
    color: var(--acc);
    text-shadow: 0 0 6px var(--acc);
  }
  ytd-toggle-theme-compact-link-renderer:hover::before,
  #endpoint.yt-simple-endpoint.ytd-guide-entry-renderer:hover::before {
    content: ""; display: block; background: var(--acc); width: 4px; height: 4px; position: absolute; left: 6px;
  }

  /* Clip Path Logic for Sidebar */
  ytd-guide-entry-renderer,
  #endpoint.yt-simple-endpoint.ytd-guide-entry-renderer:hover {
    border-radius: 0;
    --clipper: calc(100% - 1.5em); --clipper2: calc(0% + 0em);
    clip-path: polygon(var(--clipper2) 0%, var(--clipper) 0, 100% var(--clipper2), 100% var(--clipper), var(--clipper) 100%, var(--clipper2) 100%, 0 var(--clipper), 0 var(--clipper2));
  }

  /* Fonts */
  * { font-family: Default, system-ui, Roboto, sans-serif !important; }

  /* --- VARIABLES CONFIGURATION (Gold & Black) --- */
  *, html, [dark], [light], html[dark], html[light] {
    /* Main Gold Accent */
    --acc: #c9ae18; 
    /* Secondary Gold Accent */
    --acc2: #e0c320; 
    /* Transparent Gold */
    --acc3: rgba(201, 174, 24, 0.2); 
    --acc4: rgba(201, 174, 24, 0.5);

    /* Backgrounds - FORCED BLACK */
    --bg2: #000000; /* Pure Black */
    --bg1: #050505; /* Off Black */
    --bg0: rgba(10, 10, 10, 0.95); /* Panels */
    --bg3: #c9ae18; 
    --bg4: #c9ae18;

    /* Text Colors */
    --tx1: #c9ae18; /* Main Gold Text */
    --tx2: #ffffff; /* Secondary White Text */
    --tx3: #c9ae18;
    --tx4: #ffffff;
    --tx5: #c9ae18;

    /* Glows & Logos */
    --lg1: #c9ae18;
    --lg2: #c9ae18;
    --lg3: #c9ae18;
    --lg4: #ffffff;
    --topicons: #c9ae18;

    /* Layout & Geometry */
    --bw: 0.2em;
    --bw2: 0.12em;
    --es: 1.5em;
    --es2: 0.7em;
    
    /* FIX: CHANGED FROM 1 TO 0.3 TO ALLOW IMAGE TO SHOW */
    --bgoppa: 0.3; 
    
    --oppa: 0.95;
    
    /* Standard YouTube overrides */
    --yt-spec-base-background: var(--bg2);
    --yt-spec-raised-background: var(--bg0) !important;
    --yt-spec-text-primary: var(--tx2) !important;
    --yt-spec-text-secondary: var(--tx1);
    --yt-spec-icon-active-other: var(--acc);
    --yt-spec-icon-inactive: #666;
    --yt-spec-brand-icon-active: var(--acc);
    --yt-spec-brand-icon-inactive: #666;
    --yt-live-chat-paid-message-primary-color: var(--acc);
    
    /* Polygons & Clip Paths */
    --poly1: polygon(var(--es) 0, calc(100% - var(--es)) 0, 100% var(--es), 100% calc(100% - var(--es)), calc(100% - var(--es)) 100%, calc(0% + var(--es)) 100%, 0 calc(100% - var(--es)), 0 var(--es));
    --poly2: polygon(calc(var(--es) + 0.5%) var(--bw), calc(99.5% - var(--es)) var(--bw), calc(100% - var(--bw)) calc(0.5% + var(--es)), calc(100% - var(--bw)) calc(99.5% - var(--es)), calc(99.5% - var(--es)) calc(100% - var(--bw)), calc(0.5% + var(--es)) calc(100% - var(--bw)), var(--bw) calc(99.5% - var(--es)), var(--bw) calc(var(--es) + 0.5%));
    
    --poly-search: polygon(var(--es) 0, 100% 0, 100% calc(0% + var(--es)), 100% calc(100% - var(--es)), 100% 100%, 0% 100%, 0 calc(100% - var(--es)), 0 var(--es));
    --poly-search2: polygon(calc(var(--es) + 0%) var(--bw), calc(100% - var(--es)) var(--bw), calc(100% - var(--bw)) calc(0% + var(--bw)), calc(100% - var(--bw)) calc(99.5% - var(--bw)), calc(100% - var(--es)) calc(100% - var(--bw)), calc(0% + var(--bw)) calc(100% - var(--bw)), var(--bw) calc(99.5% - var(--es)), var(--bw) calc(var(--es) + 0.5%));
    
    --poly-search-down: polygon(0 0, 100% 0, 100% calc(0% + var(--es)), 100% calc(100% - var(--es)), calc(100% - var(--es)) 100%, calc(0% + var(--es)) 100%, 0 calc(100% - var(--es)), 0 var(--es));
    --poly-search-down2: polygon(var(--bw) var(--bw), calc(100% - var(--bw)) var(--bw), calc(100% - var(--bw)) calc(0.5% + var(--es)), calc(100% - var(--bw)) calc(99.5% - var(--es)), calc(99.5% - var(--es)) calc(100% - var(--bw)), calc(0.5% + var(--es)) calc(100% - var(--bw)), var(--bw) calc(99.5% - var(--es)), var(--bw) calc(var(--es) + 0.5%));
    
    --poly-filter-down1: polygon(0 0, 100% 0, 100% calc(0% + var(--es2)), 100% calc(100% - var(--es2)), calc(100% - var(--es2)) 100%, calc(0% + var(--es2)) 100%, 0 calc(100% - var(--es2)), 0 var(--es));
    --poly-filter-down2: polygon(var(--bw2) var(--bw2), calc(100% - var(--bw2)) var(--bw2), calc(100% - var(--bw2)) calc(0.5% + var(--es2)), calc(100% - var(--bw2)) calc(99.5% - var(--es2)), calc(99.5% - var(--es2)) calc(100% - var(--bw2)), calc(0.5% + var(--es2)) calc(100% - var(--bw2)), var(--bw2) calc(99.5% - var(--es2)), var(--bw2) calc(var(--es2) + 0.5%));
  }
}
